let t = 0.0;
let vel = 0.02;
let num;
let paletteSelected;
let paletteSelected1;
let paletteSelected2;
let waterPalette = [
	"#e0f7fa", // 淡い水色（浅瀬、泡）
	"#b2ebf2", // 明るい水色（透明感）
	"#4dd0e1", // 中間の青（流れ）
	"#0097a7", // 深めの青（川や海の深さ）
	"#01579b", // ダークブルー（深海、影）
	"#ffffff", // 白（光の反射、波のハイライト）
	"#cceeff", // 空の反映、水面
	"#003f5c" // 最も深いところ、冷たい水
];

function setup() {
	createCanvas(800, 800);
	pixelDensity(2)
	rectMode(CENTER)
	angleMode(DEGREES);
	num = random(100000);
	paletteSelected = random(palettes);
	paletteSelected1 = random(palettes);
	paletteSelected2 = random(palettes);
	pg2 = createGraphics(width, height);
	pg2.noStroke();
	let particle_count2 = (width * height) * 0.005;
	for (let i = 0; i < particle_count2; i++) {
		let x = random(width);
		let y = random(height);
		let n = noise(x * 0.1, y * 0.1) * ((width + height) / 2 * 0.01);
		pg2.rotate(n)
		let col = color(random(waterPalette))
		//col.setAlpha(100)
		pg2.fill(col);
		pg2.ellipse(x, y, n, n);
	}
}


function draw() {
	randomSeed(num);
	background(51);
	stroke("#355070");
	t += vel;
	for (let i = 1; i < 10; i++) {
		sinCircle(width / 2, height / 2, width * 0.01 * i);
		sinCircle(width / 2, height / 2, width / i);
		//sinCircle(width / 2, height / 2, width * 0.2);
	}
	push();
	blendMode(SCREEN)
	drawingContext.filter = "blur(" + int(random(10)) + "px)"
	image(pg2, 0, 0)
	pop();
}

function randomCol() {
	let randoms = int(random(1, paletteSelected.length));
	return color(paletteSelected[randoms]);
}

function gradient(r) {
	col1 = color(random(waterPalette));
	col1.setAlpha(30)
	col2 = random(waterPalette);

	noStroke();
	let gradientFill = drawingContext.createLinearGradient(
		0,
		-r,
		0,
		r
	);
	gradientFill.addColorStop(0, color(col1));
	gradientFill.addColorStop(1, color(col2));
	drawingContext.fillStyle = gradientFill;
}

function sinCircle(x, y, r) {
	push();
	translate(x, y);
	rotate(45)
	let radius = r; //半径
	let n = 100
	for (let i = 0; i < 360; i += floor(360 / n)) {
		let ex = radius * sin(i);
		let ey = radius * cos(i);
		ellipse(ex, ey, 1, 1);
		//text(i,ex,ey)
		// if(i<90){
		push();
		translate(ex, ey)
		rotate(atan2(ey, ex))
		shape(0, 0, r * random(0.2, 1.5))
		pop();
		//	}
	}
	pop();
}

function shape(x, y, r) {
	push();
	//fill(randomCol())
	gradient(r)
	let d1 = r * 0.1
	let d2 = r * 0.05
	let d3 = r * random(0.1, 0.3)
	let d4 = r * 0.15
	let center = r * 0.5;

	translate(x, y);
	// line(0, 0, 0, r)
	// ellipse(0, 0, d1) //ねもと
	// ellipse(0,center,d2)//中央
	// ellipse(0, r, d3)//水滴先端

	beginShape()

	vertex(-d1 / 2, 0)
	// bezierVertex(x2, y2, x3, y3,-d2/2,center)
	bezierVertex(-d2 * 0.2, r * 0.2, d4 * 0.1, center * 1.5, -d4 * 0.5, r - (d3 / 2))
	bezierVertex(-d3 / 2, r - (d3 * 0.2), -d3 * 0.5, r - (d3 * 0.1), -d3 / 2, r)
	bezierVertex(-d3 / 2, r + (d3 * 0.4), -d3 * 0.15, r + (d3 / 2), 0, r + (d3 / 2))
	bezierVertex(d3 * 0.15, r + (d3 / 2), d3 / 2, r + (d3 * 0.4), d3 / 2, r)
	bezierVertex(d3 * 0.5, r - (d3 * 0.1), d3 / 2, r - (d3 * 0.2), d4 * 0.5, r - (d3 / 2));
	bezierVertex(-d4 * 0.1, center * 1.5, d2 * 0.2, r * 0.2, d1 / 2, 0)


	endShape();
	fill(255, 30)
	ellipse(-d3 * 0.2, r, r * 0.03)
	fill(255, 50)
	ellipse(-d3 * 0.2, r, r * 0.01)
	pop();
}

